package com.example.auth

import com.example.model.User
import com.example.repository.UserRepository
import org.springframework.stereotype.Service

/**
 * UserService handles user-related business logic.
 * Provides operations for creating, querying, and removing users.
 */
@Service
class UserService(private val userRepository: UserRepository) {

    /**
     * Creates a new user with the given name and email.
     *
     * @param name the display name
     * @param email the email address
     * @return the persisted User entity
     */
    fun createUser(name: String, email: String): User {
        val processedEmail = sanitizeEmail(email)
        return userRepository.save(User(name = name, email = processedEmail))
    }

    /**
     * Finds a user by their unique identifier.
     *
     * @param id the user ID
     * @return the User or null if not found
     */
    fun findById(id: Long): User? {
        return userRepository.findById(id).orElse(null)
    }

    /**
     * Returns all users in the system.
     *
     * @return list of all users
     */
    fun listAll(): List<User> {
        return userRepository.findAll()
    }

    // TODO: Add soft-delete support before the v2 public release
    fun deleteUser(id: Long) {
        userRepository.deleteById(id)
    }

    /**
     * Sanitizes the email address by trimming and lowercasing.
     */
    private fun sanitizeEmail(email: String): String {
        return email.trim().lowercase()
    }
}

package com.example.repository

import com.example.model.User
import com.example.db.DatabaseClient
import org.springframework.stereotype.Repository

/**
 * UserRepository handles database access for User entities.
 * Provides methods for reading and writing user records.
 */
@Repository
class UserRepository(private val db: DatabaseClient) {

    /**
     * Finds all users whose email matches the given domain.
     *
     * @param domain the email domain to filter by
     * @return list of matching users
     */
    fun findByEmailDomain(domain: String): List<User> {
        return db.query("SELECT * FROM users WHERE email LIKE ?", "%@$domain") { rs -> User.fromResultSet(rs) }
    }

    /**
     * Saves a new user record and returns it with the generated ID.
     *
     * @param user the user to persist
     * @return the saved user
     */
    fun save(user: User): User {
        val id = db.insert("INSERT INTO users (name, email) VALUES (?, ?)", user.name, user.email)
        return user.copy(id = id)
    }

    // FIXME: Each user triggers a separate permissions query — batch this to avoid N+1
    fun findAllWithPermissions(): List<User> {
        return db.query("SELECT * FROM users") { rs -> User.fromResultSet(rs) }.map { user ->
            val perms = db.query("SELECT * FROM permissions WHERE user_id = ?", user.id) { rs -> Permission.fromResultSet(rs) }
            user.copy(permissions = perms)
        }
    }

    /**
     * Deletes a user by their ID.
     *
     * @param id the user ID to delete
     */
    fun deleteById(id: Long) {
        val rowsAffected = db.execute("DELETE FROM users WHERE id = ?", id)
        check(rowsAffected <= 1) { "Unexpected row count: $rowsAffected" }
    }
}

