/// UserViewModel manages the state for the user profile screen.
/// It loads user data and exposes it to the view layer.
final class UserViewModel: ObservableObject {

    // MARK: - Published State

    @Published var username: String = ""
    @Published var email: String = ""
    @Published var isLoading: Bool = false
    @Published var errorMessage: String? = nil

    private let userService: UserService
    private var cancellables = Set<AnyCancellable>()

    /// Initializes the view model with a user service.
    /// - Parameter userService: the service used to fetch users
    init(userService: UserService) {
        self.userService = userService
    }

    /// Loads the user with the given ID.
    /// - Parameter userId: the raw user identifier
    func loadUser(userId: String) {
        isLoading = true
        let formattedId = formatUserId(userId)
        userService.fetchUser(id: formattedId)
            .receive(on: DispatchQueue.main)
            .sink(receiveCompletion: { [weak self] completion in
                self?.isLoading = false
                if case .failure(let error) = completion {
                    self?.errorMessage = error.localizedDescription
                }
            }, receiveValue: { [weak self] user in
                self?.username = user.name
                self?.email = user.email
            })
            .store(in: &cancellables)
    }

    // MARK: - Input Validation

    /// Returns whether the current email address is valid.
    var isEmailValid: Bool {
        return email.contains("@") && email.contains(".")
    }

    /// Returns whether the username field is non-empty.
    var isUsernameValid: Bool {
        return !username.trimmingCharacters(in: .whitespaces).isEmpty
    }

    /// Formats the raw user ID for the API.
    private func formatUserId(_ id: String) -> String {
        return "usr_\(id.lowercased())"
    }
}

package com.example.util

/**
 * Utility object for common string transformations.
 * Provides capitalize, truncate, and case-conversion helpers.
 */
object StringUtils {

    /**
     * Capitalizes the first character of the input string.
     *
     * @param input the string to capitalize
     * @return the capitalized string
     */
    fun capitalize(input: String): String {
        return input.replaceFirstChar { it.uppercaseChar() }
    }

    /**
     * Truncates a string to the given length, appending a suffix if cut.
     *
     * @param input the string to truncate
     * @param maxLength the maximum number of characters
     * @param suffix the trailing suffix when truncated
     * @return the truncated string
     */
    fun truncate(input: String, maxLength: Int, suffix: String = "..."): String {
        return if (input.length <= maxLength) input else input.take(maxLength) + suffix
    }

    /**
     * Converts a camelCase string to snake_case.
     *
     * @param input the camelCase string
     * @return the snake_case equivalent
     */
    fun camelToSnake(input: String): String {
        return buildSnakeCase(input)
    }

    // FIXME: Locale-sensitive uppercasing breaks Turkish dotless-i — pass explicit Locale when upgrading
    fun uppercaseLocale(input: String): String {
        return input.uppercase()
    }

    /**
     * Builds the snake_case representation of a camelCase string.
     */
    private fun buildSnakeCase(input: String): String {
        return input.fold(StringBuilder()) { sb, c ->
            if (c.isUpperCase() && sb.isNotEmpty()) sb.append('_')
            sb.append(c.lowercaseChar())
        }.toString()
    }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { AuthToken, LoginCredentials } from './auth.types';

/**
 * AuthService manages authentication state.
 * Handles login, logout, and token persistence for the application.
 */
@Injectable({ providedIn: 'root' })
export class AuthService {
  private readonly tokenKey = 'auth_token';

  constructor(private http: HttpClient) {}

  /**
   * Authenticates the user with the provided credentials.
   * @param credentials the username and password pair
   * @returns an observable emitting the auth token on success
   */
  login(credentials: LoginCredentials): Observable<AuthToken> {
    const endpoint = '/api/auth/login';
    return this.http.post<AuthToken>(endpoint, credentials);
  }

  /**
   * Removes the stored token, logging the user out.
   */
  logout(): void {
    localStorage.removeItem(this.tokenKey);
  }

  /**
   * Returns the raw token string from local storage.
   * @returns the token or null if absent
   */
  getToken(): string | null {
    return localStorage.getItem(this.tokenKey);
  }

  /**
   * Persists the given token to local storage.
   * @param token the token object to store
   */
  storeToken(token: AuthToken): void {
    const serialized = JSON.stringify(token);
    localStorage.setItem(this.tokenKey, serialized);
  }

  // TODO: Implement token refresh logic before production deployment
  isTokenExpired(): boolean {
    const token = this.getToken();
    if (!token) return true;
    const parsed = JSON.parse(token);
    return Date.now() > parsed.expiresAt;
  }
}

