                Text(message)
                    .foregroundColor(.red)
                    .font(.caption)
            }

            Button(action: handleLogin) {
                loginButtonLabel()
            }
            .disabled(viewModel.isLoading)
        }
        .padding()
    }

    // MARK: - Actions

    /// Triggers the login flow on the view model.
    private func handleLogin() {
        viewModel.login()
    }

    // MARK: - View Helpers

    /// Returns the label view for the login button.
    private func loginButtonLabel() -> some View {
        Group {
            if viewModel.isLoading {
                ProgressView()
            } else {
                Text("Log In").bold()
            }
        }
    }
