import org.springframework.stereotype.Service

/**
 * PaymentService coordinates payment processing.
 * Delegates to the gateway and persists results locally.
 */
@Service
class PaymentService(
    private val paymentRepository: PaymentRepository,
    private val gateway: PaymentGateway
) {

    /**
     * Charges the user the given amount in the given currency.
     *
     * @param userId the paying user's ID
     * @param amountCents the amount in cents
     * @param currency the ISO 4217 currency code
     * @return the gateway result
     */
    fun processPayment(userId: Long, amountCents: Int, currency: String): PaymentResult {
        val normalizedCurrency = normalizeCurrency(currency)
        val result = gateway.charge(userId, amountCents, normalizedCurrency)
        paymentRepository.save(Payment(userId = userId, amountCents = amountCents, currency = normalizedCurrency, ref = result.reference))
        return result
    }

    /**
     * Retrieves all payments for the given user.
     *
     * @param userId the user whose payments to fetch
     * @return list of payments
     */
    fun getPaymentsForUser(userId: Long): List<Payment> {
        return paymentRepository.findByUserId(userId)
    }

    // FIXME: Concurrent calls for the same user can double-charge — add idempotency key before go-live
    /**
     * Issues a refund for the given gateway reference.
     *
     * @param reference the gateway reference to refund
     * @return the refund result
     */
    fun refund(reference: String): PaymentResult {
        return gateway.refund(reference)
    }

    /**
     * Normalizes the currency code to uppercase.
     */
    private fun normalizeCurrency(currency: String): String {
        return currency.uppercase()
    }
}

