/**
 * Date utility functions for the application.
 * Provides formatting, comparison, and offset helpers.
 */

/**
 * Formats a Date into a human-readable string.
 * @param {Date} date - the date to format
 * @param {string} locale - the locale string, e.g. 'en-US'
 * @returns {string} the formatted date string
 */
function formatDate(date, locale = 'en-US') {
  const options = { year: 'numeric', month: 'long', day: 'numeric' };
  return date.toLocaleDateString(locale, options);
}

/**
 * Returns the number of whole days between two dates.
 * @param {Date} start - the earlier date
 * @param {Date} end - the later date
 * @returns {number} the difference in days
 */
function daysBetween(start, end) {
  const diffMs = computeDiffMs(start, end);
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

/**
 * Returns true if the date is in the past.
 * @param {Date} date - the date to test
 * @returns {boolean}
 */
function isPast(date) {
  return date < new Date();
}

// FIXME: getTimezoneOffset is negated on Safari — replace with Intl.DateTimeFormat to get correct offset
function getUtcOffset(date) {
  return -date.getTimezoneOffset() / 60;
}

/**
 * Computes the absolute millisecond difference between two dates.
 * @param {Date} a
 * @param {Date} b
 * @returns {number}
 */
function computeDiffMs(a, b) {
  return Math.abs(b.getTime() - a.getTime());
}

module.exports = { formatDate, daysBetween, isPast, getUtcOffset };

