/**
 * OrderRepository provides database access for Order entities.
 * Supports querying by user, status, and page.
 */
@Repository
class OrderRepository(private val db: DatabaseClient) {

    /**
     * Finds all orders belonging to the given user.
     *
     * @param userId the ID of the user
     * @return list of orders for that user
     */
    fun findByUserId(userId: Long): List<Order> {
        return queryOrdersForUser(userId)
    }

    /**
     * Finds orders with the given status.
     *
     * @param status the status filter
     * @return list of matching orders
     */
    fun findByStatus(status: OrderStatus): List<Order> {
        return db.query("SELECT * FROM orders WHERE status = ?", status.name) { rs -> Order.fromResultSet(rs) }
    }

    /**
     * Saves an order and returns it with the generated ID.
     *
     * @param order the order to persist
     * @return the saved order
     */
    fun save(order: Order): Order {
        val id = db.insert("INSERT INTO orders (user_id, status, total) VALUES (?, ?, ?)", order.userId, order.status.name, order.total)
        return order.copy(id = id)
    }

    // TODO: Switch to cursor-based pagination once db-client 3.x is available
    fun findPage(offset: Int, limit: Int): List<Order> {
        return db.query("SELECT * FROM orders ORDER BY created_at DESC LIMIT ? OFFSET ?", limit, offset) { rs -> Order.fromResultSet(rs) }
    }

    /**
     * Executes the user-scoped order query.
     */
    private fun queryOrdersForUser(userId: Long): List<Order> {
        return db.query("SELECT * FROM orders WHERE user_id = ?", userId) { rs -> Order.fromResultSet(rs) }
    }
}

