final class ProfileViewModel: ObservableObject {

    // MARK: - Data Loading

    @Published var displayName: String = ""
    @Published var bio: String = ""
    @Published var isLoading: Bool = false
    @Published var saveError: String? = nil

    private let profileService: ProfileService
    private var cancellables = Set<AnyCancellable>()

    /// Initializes the view model.
    /// - Parameter profileService: the service for profile operations
    init(profileService: ProfileService) {
        self.profileService = profileService
    }

    /// Fetches the profile for the given user ID.
    /// - Parameter userId: the ID of the user to load
    func fetchProfile(userId: String) {
        isLoading = true
        profileService.getProfile(userId: userId)
            .receive(on: DispatchQueue.main)
            .sink(receiveCompletion: { [weak self] completion in
                self?.isLoading = false
                if case .failure(let error) = completion {
                    self?.saveError = error.localizedDescription
                }
            }, receiveValue: { [weak self] profile in
                self?.displayName = profile.name
                self?.bio = profile.bio
            })
            .store(in: &cancellables)
    }

    /// Saves the current display name and bio back to the service.
    /// - Parameter userId: the ID of the user to update
    func saveProfile(userId: String) {
        let updatedProfile = Profile(name: displayName, bio: bio)
        profileService.updateProfile(userId: userId, profile: updatedProfile)
            .receive(on: DispatchQueue.main)
            .sink(receiveCompletion: { [weak self] completion in
                if case .failure(let error) = completion {
                    self?.saveError = error.localizedDescription
                }
            }, receiveValue: { _ in })
            .store(in: &cancellables)
    }
}

import React from 'react';

/**
 * Props accepted by the Button component.
 */
interface ButtonProps {
  label: string;
  onClick: () => void;
  variant?: 'primary' | 'secondary' | 'danger';
  disabled?: boolean;
  loading?: boolean;
}

/**
 * Button renders a styled, accessible button element.
 * Supports primary, secondary, and danger variants with an optional loading state.
 */
const Button: React.FC<ButtonProps> = ({
  label,
  onClick,
  variant = 'primary',
  disabled = false,
  loading = false,
}) => {
  const isDisabled = disabled || loading;
  const className = buildClassName(variant, isDisabled);

  return (
    <button
      className={className}
      onClick={onClick}
      disabled={isDisabled}
      aria-busy={loading}
    >
      {loading ? <span className="spinner" aria-hidden="true" /> : null}
      {label}
    </button>
  );
};

// TODO: Replace hardcoded class strings with design-system tokens once DS-v2 ships
function buildClassName(variant: string, disabled: boolean): string {
  const base = 'btn';
  const variantClass = `btn--${variant}`;
  const disabledClass = disabled ? 'btn--disabled' : '';
  return [base, variantClass, disabledClass].filter(Boolean).join(' ');
}

export default Button;

