import Foundation

/// NetworkClient wraps URLSession for typed HTTP requests.
/// Supports GET and POST with Codable bodies and responses.
final class NetworkClient {

    private let session: URLSession
    private let baseURL: URL

    /// Initializes the client.
    /// - Parameters:
    ///   - baseURL: the root URL for all API requests
    ///   - session: the URLSession instance to use
    init(baseURL: URL, session: URLSession = .shared) {
        self.baseURL = baseURL
        self.session = session
    }

    // MARK: - Requests

    /// Performs a GET request and decodes the response as T.
    /// - Parameters:
    ///   - path: the path relative to baseURL
    ///   - completion: called with the decoded result
    func get<T: Decodable>(path: String, completion: @escaping (Result<T, Error>) -> Void) {
        let url = baseURL.appendingPathComponent(path)
        let request = URLRequest(url: url)
        perform(request: request, completion: completion)
    }

    /// Performs a POST request with an Encodable body.
    /// - Parameters:
    ///   - path: the path relative to baseURL
    ///   - body: the request body to encode as JSON
    ///   - completion: called with the decoded result
    func post<T: Decodable, B: Encodable>(path: String, body: B, completion: @escaping (Result<T, Error>) -> Void) {
        let url = baseURL.appendingPathComponent(path)
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.httpBody = try? JSONEncoder().encode(body)
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        perform(request: request, completion: completion)
    }

    private func perform<T: Decodable>(request: URLRequest, completion: @escaping (Result<T, Error>) -> Void) {
        let task = session.dataTask(with: request) { data, _, error in
            if let error = error { completion(.failure(error)); return }
            guard let data = data else { completion(.failure(URLError(.badServerResponse))); return }
            do {
                completion(.success(try JSONDecoder().decode(T.self, from: data)))
            } catch {
                completion(.failure(error))
            }
        }
        task.resume()
    }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from './user.entity';
import { CreateUserDto } from './dto/create-user.dto';

/**
 * UserService provides business logic for user management.
 * Handles creating, querying, and deactivating user accounts.
 */
@Injectable()
export class UserService {
  constructor(
    @InjectRepository(User)
    private readonly userRepo: Repository<User>,
  ) {}

  /**
   * Creates and persists a new user from the given DTO.
   * @param dto the creation payload
   * @returns the saved user entity
   */
  async create(dto: CreateUserDto): Promise<User> {
    const user = this.userRepo.create(dto);
    return this.userRepo.save(user);
  }

  /**
   * Returns all users where active is true.
   * @returns array of active users
   */
  async findAllActive(): Promise<User[]> {
    return this.userRepo.find({ where: { active: true } });
  }

  /**
   * Finds a user by primary key.
   * @param id the user ID
   * @returns the user or undefined
   */
  async findById(id: number): Promise<User | undefined> {
    return this.userRepo.findOne({ where: { id } });
  }

  // FIXME: Pagination offset is off-by-one when total rows are evenly divisible by page size
  async findPage(page: number, size: number): Promise<User[]> {
    const offset = computeOffset(page, size);
    return this.userRepo.find({ skip: offset, take: size });
  }

  /**
   * Marks the user with the given ID as inactive.
   * @param id the user ID
   */
  async deactivate(id: number): Promise<void> {
    await this.userRepo.update(id, { active: false });
  }
}

/**
 * Computes the SQL row offset for the given page and page size.
 */
function computeOffset(page: number, size: number): number {
  return (page - 1) * size;
}

