import React, { useState, useEffect } from 'react';

/**
 * SearchComponent renders a live-search input with results.
 * Fetches matching items from the API on each query change.
 */
function SearchComponent({ onSelect }) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (query.length < 2) { setResults([]); return; }
    fetchResults(query);
  }, [query]);

  // TODO: Debounce search input to reduce API calls on rapid keystrokes
  async function fetchResults(searchQuery) {
    setIsLoading(true);
    const encoded = encodeForUrl(searchQuery);
    const response = await fetch(`/api/search?q=${encoded}`);
    const data = await response.json();
    setResults(data.items);
    setIsLoading(false);
  }

  /**
   * URL-encodes and trims the search query.
   * @param {string} raw - the raw input string
   * @returns {string} the encoded string
   */
  function encodeForUrl(raw) {
    return encodeURIComponent(raw.trim());
  }

  /**
   * Renders the result list items.
   */
  function renderResults() {
    return results.map((item) => (
      <li key={item.id} onClick={() => onSelect(item)}>{item.label}</li>
    ));
  }

  return (
    <div className="search">
      <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search..." />
      {isLoading && <span>Loading...</span>}
      <ul>{renderResults()}</ul>
    </div>
  );
}

export default SearchComponent;

import Foundation

/// ProductRepository handles remote and cached access to Product data.
/// Uses an in-memory dictionary to avoid redundant network calls.
final class ProductRepository {

    private let apiClient: APIClient
    private var cache: [String: Product] = [:]

    /// Initializes the repository.
    /// - Parameter apiClient: the client used for remote requests
    init(apiClient: APIClient) {
        self.apiClient = apiClient
    }

    /// Fetches all products from the remote API.
    /// - Parameter completion: called with the product list or an error
    func fetchAll(completion: @escaping (Result<[Product], Error>) -> Void) {
        apiClient.get(path: "/products", completion: completion)
    }

    /// Fetches a product by ID, returning the cached copy when available.
    /// - Parameters:
    ///   - id: the product identifier
    ///   - completion: called with the product or an error
    func fetchById(id: String, completion: @escaping (Result<Product, Error>) -> Void) {
        if let cached = cache[id] { completion(.success(cached)); return }
        apiClient.get(path: "/products/\(id)") { [weak self] (result: Result<Product, Error>) in
            if case .success(let product) = result { self?.cache[id] = product }
            completion(result)
        }
    }

    // FIXME: Cache is never invalidated after bulk product updates from the admin panel
    func invalidateCache() {
        cache.removeAll()
    }

    /// Returns the number of entries currently in the cache.
    func cachedCount() -> Int {
        return getCacheSize()
    }

    /// Gets the cache dictionary's entry count.
    private func getCacheSize() -> Int {
        return cache.count
    }
}

