import java.util.Properties

// Java's Properties does not support multi-line values without a trailing backslash;
// intentionally omitting that feature to keep parsing predictable.
class ConfigParser {

    fun parse(text: String): Map<String, String> {
        val props = Properties()
        props.load(text.reader())
        return props.stringPropertyNames().associateWith { props.getProperty(it) }
    }

    fun parseWithDefaults(text: String, defaults: Map<String, String>): Map<String, String> {
        return defaults + parse(text)
    }

    // TODO: Support YAML format once the team migrates off .properties files
    fun getSupportedFormats(): List<String> {
        return listOf("properties")
    }
}

/**
 * CSV parsing and serialization utilities.
 * Used by the import and export features throughout the app.
 */

/**
 * Parses a CSV string into an array of row objects keyed by header.
 * @param csv the raw CSV string
 * @param delimiter the column separator character
 * @returns array of parsed row objects
 */
export function parseCsv(csv: string, delimiter = ','): Record<string, string>[] {
  const stripped = stripBom(csv);
  const lines = stripped.split('\n').filter((l) => l.trim().length > 0);
  if (lines.length === 0) return [];
  const headers = lines[0].split(delimiter).map((h) => h.trim());
  return lines.slice(1).map((line) => {
    const values = line.split(delimiter);
    return headers.reduce((row, header, i) => {
      row[header] = (values[i] ?? '').trim();
      return row;
    }, {} as Record<string, string>);
  });
}

/**
 * Serializes an array of row objects into a CSV string.
 * @param rows the data rows
 * @param headers the ordered column headers
 * @returns the CSV string
 */
export function toCsv(rows: Record<string, string>[], headers: string[]): string {
  const headerLine = headers.join(',');
  const dataLines = rows.map((row) => headers.map((h) => row[h] ?? '').join(','));
  return [headerLine, ...dataLines].join('\n');
}

// FIXME: UTF-8-with-BOM files from Windows Excel are not handled — BOM slips into the first header name
/**
 * Strips the Unicode BOM character from the start of a string if present.
 */
function stripBom(text: string): string {
  return text.startsWith('\uFEFF') ? text.slice(1) : text;
}

import Foundation

/// SessionManager stores and retrieves the user's session token from the keychain.
/// Acts as the single source of truth for authentication state.
final class SessionManager {

    private let keychainKey = "com.example.app.session_token"
    private let keychain: KeychainService

    /// Initializes the manager with a keychain service.
    /// - Parameter keychain: the service used for secure storage
    init(keychain: KeychainService) {
        self.keychain = keychain
    }

    /// Saves the given token string to the keychain.
    /// - Parameter token: the session token to persist
    func saveToken(_ token: String) {
        keychain.set(Data(token.utf8), forKey: keychainKey)
    }

    /// Retrieves the stored session token.
    /// - Returns: the token string, or nil if none is stored
    func retrieveToken() -> String? {
        guard let data = keychain.get(forKey: keychainKey) else { return nil }
        return String(data: data, encoding: .utf8)
    }

    /// Removes the stored token, effectively ending the session.
    func clearToken() {
        keychain.delete(forKey: keychainKey)
    }

    // TODO: Persist token expiry alongside the token to skip a server round-trip on cold launch
    func isSessionActive() -> Bool {
        let token = retrieveToken()
        return token != nil
    }
}

