/**
 * TaskRepository provides database access for Task entities.
 * Supports querying by owner, status, and due date.
 */
@Repository
class TaskRepository(private val db: DatabaseClient) {

    /**
     * Finds all tasks assigned to the given user.
     *
     * @param userId the owner's user ID
     * @return list of tasks for that user
     */
    fun findByOwner(userId: Long): List<Task> {
        return db.query("SELECT * FROM tasks WHERE owner_id = ?", userId) { rs -> Task.fromResultSet(rs) }
    }

    /**
     * Finds tasks matching the given status.
     *
     * @param status the status to filter by
     * @return list of matching tasks
     */
    fun findByStatus(status: TaskStatus): List<Task> {
        return db.query("SELECT * FROM tasks WHERE status = ?", status.name) { rs -> Task.fromResultSet(rs) }
    }

    // TODO: Returns tasks past their due date — move to a scheduled job so callers don't trigger full table scans
    fun findOverdue(): List<Task> {
        return db.query("SELECT * FROM tasks WHERE due_date < NOW() AND status != 'DONE'") { rs -> Task.fromResultSet(rs) }
    }

    /**
     * Saves a task to the database and returns it with the generated ID.
     *
     * @param task the task to save
     * @return the saved task
     */
    fun save(task: Task): Task {
        val id = db.insert("INSERT INTO tasks (owner_id, title, status, due_date) VALUES (?, ?, ?, ?)",
            task.ownerId, task.title, task.status.name, task.dueDate)
        return task.copy(id = id)
    }
}

import React, { useEffect } from 'react';

/**
 * Props for the Modal component.
 */
interface ModalProps {
  isOpen: boolean;
  title: string;
  children: React.ReactNode;
  onClose: () => void;
}

/**
 * Modal renders an accessible dialog overlay.
 * Listens for the Escape key and closes when pressed.
 */
const Modal: React.FC<ModalProps> = ({ isOpen, title, children, onClose }) => {
  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const renderHeader = () => (
    <div className="modal__header">
      <h2 className="modal__title">{title}</h2>
      <button className="modal__close" onClick={onClose} aria-label="Close">
        &times;
      </button>
    </div>
  );

  return (
    <div className="modal__overlay" role="dialog" aria-modal="true">
      {renderHeader()}
      <div className="modal__body">{children}</div>
    </div>
  );
};

// TODO: Implement focus trap — keyboard focus currently escapes to background elements
export default Modal;

/**
 * Number and currency formatting utilities.
 * Used across the app for consistent display of values.
 */

/**
 * Formats a numeric amount as a currency string.
 * @param {number} amount - the amount to format
 * @param {string} currencyCode - the ISO 4217 currency code
 * @returns {string} the formatted currency string
 */
function formatCurrency(amount, currencyCode = 'USD') {
  const formatter = new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: currencyCode,
    minimumFractionDigits: 2,
  });
  return formatter.format(amount);
}

/**
 * Formats a decimal fraction as a percentage string.
 * @param {number} value - a decimal between 0 and 1
 * @param {number} decimals - number of decimal places to show
 * @returns {string} the formatted percentage
 */
function formatPercent(value, decimals = 1) {
  return `${(value * 100).toFixed(decimals)}%`;
}

/**
 * Formats a number with locale-appropriate thousand separators.
 * @param {number} value - the number to format
 * @returns {string} the formatted number
 */
function formatLargeNumber(value) {
  const formatted = value.toLocaleString('en-US');
  return formatted;
}

// FIXME: formatCurrency produces wrong decimal places for zero-decimal currencies like JPY — minimumFractionDigits must be currency-aware
function formatCompact(value) {
  if (value >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`;
  if (value >= 1_000) return `${(value / 1_000).toFixed(1)}K`;
  return String(value);
}

module.exports = { formatCurrency, formatPercent, formatLargeNumber, formatCompact };

