/**
 * Service for sending notifications to users.
 */
@Singleton
class UserNotificationService @Inject constructor(
    private val repository: NotificationRepository,
    private val emailClient: EmailClient
) {

    // TODO: Switch to a queue-based system once volume exceeds 10k/day

    /**
     * Sends a notification to the specified user.
     */
    fun sendNotification(user: User, notification: Notification) {
        val subject = buildEmailSubject(notification)
        emailClient.send(
            to = user.email,
            subject = subject,
            body = notification.body
        )
        repository.save(notification.copy(status = NotificationStatus.SENT))
    }

    /**
     * Returns all pending notifications for a user.
     */
    fun getPendingNotifications(userId: String): List<Notification> {
        return repository.findByUserIdAndStatus(userId, NotificationStatus.PENDING)
    }

    /**
     * Marks a notification as read.
     */
    fun markAsRead(notificationId: String) {
        val notification = repository.findById(notificationId)
            ?: throw IllegalArgumentException("Notification not found: $notificationId")
        repository.save(notification.copy(status = NotificationStatus.READ))
    }

    /**
     * Builds the email subject line from a notification.
     */
    private fun buildEmailSubject(notification: Notification): String {
        return "[${notification.type.displayName}] ${notification.title}"
    }
}

