import { Router, Request, Response } from 'express';
import { AuthService } from '../services/AuthService';
import { validateLoginBody } from '../middleware/validation';

const router = Router();
const authService = new AuthService();

// FIXME: Rate limiting is disabled until we migrate to Redis — re-enable after infra ticket #4412

/**
 * Handles user login requests.
 */
async function handleLogin(req: Request, res: Response): Promise<void> {
  const credentials = extractCredentials(req);
  try {
    const token = await authService.login(credentials.email, credentials.password);
    res.json({ token });
  } catch (err) {
    res.status(401).json({ error: 'Invalid credentials' });
  }
}

/**
 * Handles user logout requests.
 */
async function handleLogout(req: Request, res: Response): Promise<void> {
  const token = req.headers.authorization?.split(' ')[1] ?? '';
  await authService.logout(token);
  res.status(204).send();
}

/**
 * Refreshes an existing authentication token.
 */
async function handleRefresh(req: Request, res: Response): Promise<void> {
  const oldToken = req.body.token;
  try {
    const newToken = await authService.refresh(oldToken);
    res.json({ token: newToken });
  } catch (err) {
    res.status(403).json({ error: 'Token refresh failed' });
  }
}

/**
 * Extracts email and password from the request body.
 */
function extractCredentials(req: Request): { email: string; password: string } {
  return { email: req.body.email, password: req.body.password };
}

router.post('/login', validateLoginBody, handleLogin);
router.post('/logout', handleLogout);
router.post('/refresh', handleRefresh);

export default router;

/**
 * Utility functions for date formatting.
 */

// TODO: Replace with date-fns once the bundle size concern is resolved

/**
 * Pads a number to two digits with a leading zero.
 * @param {number} n - The number to pad.
 * @returns {string} The padded string.
 */
function padNumber(n) {
  return String(n).padStart(2, '0');
}

/**
 * Formats a Date object as HH:MM.
 * @param {Date} date - The date to format.
 * @returns {string} The formatted time string.
 */
function formatTime(date) {
  const hours = padNumber(date.getHours());
  const minutes = padNumber(date.getMinutes());
  return `${hours}:${minutes}`;
}

/**
 * Formats a Date object as YYYY-MM-DD.
 * @param {Date} date - The date to format.
 * @returns {string} The formatted date string.
 */
function formatDate(date) {
  const year = date.getFullYear();
  const month = padNumber(date.getMonth() + 1);
  const day = padNumber(date.getDate());
  return `${year}-${month}-${day}`;
}

/**
 * Returns a human-readable relative time string.
 * @param {Date} date - The date to compare.
 * @returns {string} Relative time like "2 hours ago".
 */
function timeAgo(date) {
  const seconds = Math.floor((Date.now() - date.getTime()) / 1000);
  if (seconds < 60) return 'just now';
  if (seconds < 3600) return `${Math.floor(seconds / 60)} minutes ago`;
  if (seconds < 86400) return `${Math.floor(seconds / 3600)} hours ago`;
  return `${Math.floor(seconds / 86400)} days ago`;
}

module.exports = { formatTime, formatDate, timeAgo };

package com.example.data

import com.example.models.Order
import com.example.models.OrderStatus
import org.springframework.stereotype.Repository
import java.time.Instant

/**
 * Repository for managing order persistence.
 */
@Repository
class OrderRepository(private val db: DatabaseClient) {

    // Using raw SQL here instead of JPA because the orders table has a non-standard
    // composite key that Hibernate maps incorrectly with our schema versioning setup.

    /**
     * Finds an order by its ID.
     */
    fun findById(orderId: String): Order? {
        val query = "SELECT * FROM orders WHERE id = ?"
        return db.queryForObject(query, orderId, Order::class.java)
    }

    /**
     * Returns all orders for a given customer.
     */
    fun findByCustomer(customerId: String): List<Order> {
        val query = "SELECT * FROM orders WHERE customer_id = ? ORDER BY created_at DESC"
        return db.query(query, customerId, Order::class.java)
    }

    /**
     * Saves or updates an order.
     */
    fun save(order: Order): Order {
        val existingOrder = findById(order.id)
        val isNew = existingOrder == null
        val timestamp = Instant.now().toEpochMilli()
        if (isNew) {
            db.execute(
                "INSERT INTO orders (id, customer_id, status, created_at) VALUES (?, ?, ?, ?)",
                order.id, order.customerId, order.status.name, timestamp
            )
        } else {
            db.execute(
                "UPDATE orders SET status = ?, updated_at = ? WHERE id = ?",
                order.status.name, timestamp, order.id
            )
        }
        return order
    }

    /**
     * Deletes an order by ID.
     */
    fun delete(orderId: String) {
        db.execute("DELETE FROM orders WHERE id = ?", orderId)
    }
}
